/** Tears every socket and server down, so a red test reports instead of hanging the run. */
export async function stopEngines(): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) await hal.stop();
}

const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

/** Waits for all clients to close, stops every server in the given arrays, and clears both. */
export async function drainAndStopEngines(clientList: WebSocket[], serverList: HalServer[]): Promise<void> {
  for (const client of clientList.splice(0)) client.terminate();
  for (const hal of serverList.splice(0)) {
    await eventually(() => hal.wss.clients.size === 0);
    await hal.stop();
  }
}

/** A minimal store wrapping only the five required members, so optional ones can be overridden per test. */
export const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

